#!/usr/bin/env python3
"""GREEK PAINTINGS' DATA (docs/greek.md): writes assets/greek/*.json -- what the engine (greek/*.js) knows of the art and
none of its logic. canon: bodies by period, in units of a figure 100 tall. actions: what a body does, as ranges a seed
picks in. Run: python3 tools/greekgen.py
"""
import json, math, os
from potshapes import fit
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "assets", "greek")
os.makedirs(OUT, exist_ok=True)


def write(name, doc):
    with open(os.path.join(OUT, name + ".json"), "w") as f:
        json.dump(doc, f, indent=1, separators=(",", ":"))
        f.write("\n")


# ---- the body: lengths, then widths as [t along the bone, in front of it, behind it] -----------------------------------
def _snake(n=22):
    # a body along a wave, thin at the tail, thick behind a wedge of head
    mid = [(-.72 + 1.3 * i / n, .4 * math.sin(i / n * 7.4 + .3)) for i in range(n + 1)]
    w = lambda i: .02 + .1 * (i / n) ** .8
    def side(i, k):
        a, b = mid[max(0, i - 1)], mid[min(n, i + 1)]
        d = math.hypot(b[0] - a[0], b[1] - a[1]) or 1
        return [round(mid[i][0] - (b[1] - a[1]) / d * w(i) * k, 3), round(mid[i][1] + (b[0] - a[0]) / d * w(i) * k, 3)]
    (x, y) = mid[n]
    return [side(i, 1) for i in range(n + 1)] + [[round(x + .04, 3), round(y + .15, 3)], [round(x + .28, 3), round(y + .02, 3), 1], [round(x + .04, 3), round(y - .15, 3)]] + [side(i, -1) for i in range(n, -1, -1)]
