def _still(seat, rings, lines=(), rail=None, cloth=None, clothRole="cloth2"):
    # furniture and monuments: under whoever sits on it, its rail and cloth over them
    parts = [{"z": 14, "role": "wood", "rings": rings, "lines": [{"cls": "detail", "pts": l} for l in lines]}]
    if rail: parts.append({"z": 80, "role": "wood", "rings": rail})
    if cloth: parts.append({"z": 81, "role": clothRole, "rings": cloth})
    return {"anchors": {"seat": seat}, "parts": parts}
def _circle(c, r, n=18):
    return [[round(c[0] + math.cos(i / n * math.tau) * r, 2), round(c[1] + math.sin(i / n * math.tau) * r, 2)] for i in range(n)]
def _car(wheel, seat, pole, rail, spokes=4):
    # a wheel with its spokes, the box above, the pole to the horses; the rail before whoever stands in it, the wheel before that
    x, y, R = wheel
    sp = [{"cls": "hem", "pts": [[round(x + math.cos(i / spokes * math.pi) * R * .84, 2), round(y + math.sin(i / spokes * math.pi) * R * .84, 2)], [round(x - math.cos(i / spokes * math.pi) * R * .84, 2), round(y - math.sin(i / spokes * math.pi) * R * .84, 2)]]} for i in range(spokes)]
    return {"anchors": {"seat": seat}, "parts": [{"z": 14, "role": "wood", "rings": pole}, {"z": 80, "role": "wood", "rings": rail}, {"z": 81, "role": "wood", "rings": [_circle((x, y), R)], "lines": [{"cls": "hem", "pts": _circle((x, y), R * .84), "closed": True}] + sp}]}
