    if "yoke" in b: parts.append({"z": 27, "role": "wood", "rings": [b.pop("yoke")], "if": "yoked"})
    return {**b, "parts": parts, "anchors": {k: b.pop(k) for k in ("seat", "front", "mouth", "rump", "breast") if k in b}}
