# ---- ornament: one cell of a band, x 0..1 along it, y 0..1 up it, `aspect` its width over height. rings filled and lines
# drawn in a slot: fg the painter's dark, accent the added colour. A band stamps whole cells only.


def fan(cx, cy, r, n, a0, a1, w):
    """petals as a fan about a point"""
    rings = []
    for i in range(n):
        a = a0 + (a1 - a0) * i / (n - 1)
        ux, uy = math.sin(a), math.cos(a)
        l = r * (1 - .28 * abs(i - (n - 1) / 2) / ((n - 1) / 2))
        rings.append([[round(cx + ux * r * .18, 3), round(cy + uy * r * .18, 3), 1], [round(cx + ux * l * .7 + uy * w, 3), round(cy + uy * l * .7 - ux * w, 3)], [round(cx + ux * l, 3), round(cy + uy * l, 3), 1], [round(cx + ux * l * .7 - uy * w, 3), round(cy + uy * l * .7 + ux * w, 3)]])
    return rings


