def _as(name, new, cast, *ids):
    # a scene with others in its roles, in every variant that names them
    S = json.loads(json.dumps(SCENES[name]))
    for i in ids: S["roles"][i]["cast"] = cast
    for v in S.get("variants", []):
        for i in ids:
            if "cast" in v.get(i, {}): v[i]["cast"] = cast
    SCENES[new] = S
