def charge(tag, cast, moves=_CHARGES):
    # a man on four legs against a man on two: a beast, who's on it, and a foe, each move a scene
    for m, M in moves.items():
        SCENES[f"{tag}-{m}"] = {"scale": .78, "wide": 1, "roles": {"h": _horse(M["gait"], M.get("face", -1)), **({"w": M["w"]} if "w" in M else {}), "a": {**_CENTAUR, "cast": cast, "face": M.get("face", -1), **M["a"]}, "b": {"face": 1, **M["b"]}}}   # (`w`: someone between them, placed before whoever reaches for her)
        if "link" in M: SCENES[f"{tag}-{m}"]["links"] = [["b", "R", *M["link"]]]
        if "press" in M: SCENES[f"{tag}-{m}"]["press"] = M["press"]
    return [f"{tag}-{m}" for m in moves]
