def pot(key, painting, name, tech, period, picture, **more):
    aspect, zones = fit(key)
    zones = [{**z, "band": {"of": BANDS[z["band"]]}} if z.get("band") in BANDS else z for z in zones]   # (a pot's ornament by its seed, its foot's rays always)
    PAINTINGS[painting] = {"name": name, "tech": tech, "period": period, "aspect": aspect, **more, "zones": [{**z, **picture, "deal": 1} if "panels" in z else z for z in zones]}
