# ---- as patterns (patterns.js layer kind `greek`, greek.js): each one painting over a W x H tile, several of a pot by seed
ROOT = os.path.join(OUT, "..")
pat = {}
def pattern(key, painting, seed=1, res=1024, W=None, H=None, across=1):
    a = PAINTINGS[painting]["aspect"]
    pat[key] = {"size": ["W", "H"], "params": {"W": W or a[0], "H": H or a[1]}, "palette": "limestone", "res": res, "layers": [{"kind": "greek", "painting": painting, "seed": seed}]}
    if across > 1: pat[key]["across"] = across   # (a layer of the tile array is square: a long painting runs over several, archmat.js)
for painting in ["bf-amphora", "rf-krater", "wg-lekythos", "hydria-rf", "kylix-rf", "kylix-rf-tondo"]:
    for k in range(1, 5):
        pattern(f"{painting}-{k}", painting, k * 7 + 1)
